  "test": "import pytest
from langfuse import observe
from langfuse._client.observe import _ContextPreservedAsyncGeneratorWrapper, _ContextPreservedSyncGeneratorWrapper


def test_dynamic_name_in_observe_decorator(langfuse_memory_client: any, memory_exporter: any) -> None:
    @observe(name=lambda a, b: f"myfunc_{a}_{b}")
    def myfunc(a: int, b: int) -> int:
        return a + b

    assert myfunc(2, 3) == 5

    # Flush the memory client to ensure spans are exported
    langfuse_memory_client.flush()

    spans = [s for s in memory_exporter.get_finished_spans() if s.name == "myfunc_2_3"]
    assert len(spans) == 1
